long long loopsum(long long n) {
    long long s = 0;
    for (long long i = 0; i < n; i++)
        s = (s + i * i) % 1000000007;
    return s;
}

#include <assert.h>
#include "loopsum.c"

int main(void) {
    assert(loopsum(0) == 0);
    assert(loopsum(10) == 285);
    assert(loopsum(1000) == 332833500);
    return 0;
}
